 static string Root=>Environment.GetEnvironmentVariable("KITAO_COLOR_TOOLS_FILM")??throw new InvalidOperationException("Explicit evidence root required");
 static string Fixture(string folder){Directory.CreateDirectory(folder);using var cms=new LcmsRgbEngine();var file=Path.Combine(folder,"p3-input.tif");var data=new float[160*112*3];for(int y=0;y<112;y++)for(int x=0;x<160;x++){int i=(y*160+x)*3;data[i]=.08f+.7f*x/159;data[i+1]=.06f+.6f*y/111;data[i+2]=.3f;}using var pixels=new HighBitDepthImageBuffer(160,112,data);AtomicTiffWriter.WriteRgb48Async(file,pixels,new(IccProfile:cms.StandardProfile("DisplayP3").Bytes())).GetAwaiter().GetResult();return file;}
 static ColorStudioToolParameter Parameter(ColorStudioNodeType type,string key)=>ColorStudioToolCatalog.GetParameters(type).Single(p=>p.Key==key);
 [TestMethod]public Task WideToolsMaskUndoVariantResourceDraftFilmAndPublishing()=>RunSta(async()=>{
  EnsureTestApplication();var dir=Path.Combine(Root,"workflow");Directory.CreateDirectory(dir);var input=Fixture(dir);var hash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(input)));using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(dir));await vm.LoadTargetAsync(input);await vm.CreateManagedColorVariantAsync(linearWide:true);Assert.IsTrue(vm.Editor.LinearDocumentEditing,vm.StatusText);var id=vm.ActiveTarget!.ActiveEditVersionId;
  vm.Editor.SetToolParameter(Parameter(ColorStudioNodeType.WhiteBalance,"temperature"),25);vm.Editor.SetToolParameter(Parameter(ColorStudioNodeType.WhiteBalance,"tint"),-10);vm.Editor.AddMaskStroke(new([new(.2,.3),new(.8,.6)],.18,.5,.7,1));vm.Editor.SelectedLayerOpacity=.65;vm.Editor.SetToolParameter(Parameter(ColorStudioNodeType.BasicTone,"contrast"),25);vm.Editor.SetToolParameter(Parameter(ColorStudioNodeType.BasicTone,"highlights"),-30);vm.Editor.SetToolParameter(Parameter(ColorStudioNodeType.BasicTone,"shadows"),20);await vm.RawLocalPreviewWork;Assert.IsTrue(vm.ActiveTarget.RawDefinition!.LocalEdits!.Stack.Nodes.All(n=>n.WideToolVersion==2));var frozen=JsonSerializer.Serialize(vm.ActiveTarget.RawDefinition);var prior=vm.Editor.ToolValue(Parameter(ColorStudioNodeType.BasicTone,"shadows"));vm.Editor.SetToolParameter(Parameter(ColorStudioNodeType.BasicTone,"shadows"),30);await vm.PhotoGradeUndoCommand.ExecuteAsync(null);await vm.RawLocalPreviewWork;Assert.AreEqual(prior,vm.Editor.ToolValue(Parameter(ColorStudioNodeType.BasicTone,"shadows")));Assert.AreEqual(frozen,JsonSerializer.Serialize(vm.ActiveTarget.RawDefinition));vm.R53Professional=true;vm.R53Professional=false;
  await vm.CreateR53VariantAsync(false);vm.Editor.SelectedLayerOpacity=.2;await vm.SwitchEditVersionAsync(id!.Value);Assert.AreEqual(frozen,JsonSerializer.Serialize(vm.ActiveTarget.RawDefinition));using var document=DocumentColorWorkflowV1.RenderResult(vm.ActiveTarget.LinearRawMaster!,vm.ActiveTarget.RawDefinition,id);var pixelHash=Convert.ToHexString(SHA256.HashData(System.Runtime.InteropServices.MemoryMarshal.AsBytes(document.Pixels.Rgb32.Span)));var project=Path.Combine(dir,"wide-tools.ptstudio.json");await vm.SaveSessionAsync(project);File.WriteAllText(Path.Combine(dir,"wide-definition.json"),frozen);File.WriteAllText(Path.Combine(dir,"wide-hash.txt"),pixelHash);
  var exports=new List<object>();foreach(var format in new[]{StudioExportFormat.Jpeg,StudioExportFormat.Tiff}){var outDir=Path.Combine(dir,"user-"+format);Directory.CreateDirectory(outDir);var dialogs=new Dialogs(outDir);using var exported=new ReferenceColorWorkspaceViewModel(dialogs);await exported.LoadSessionAsync(project);exported.QuickExportFormat=format;exported.ActiveTarget!.IsSelected=true;await exported.ExportSelectedCommand.ExecuteAsync(null);Assert.AreEqual(ReferenceExportStatus.Succeeded,exported.ActiveTarget.ExportStatus,exported.ActiveTarget.Error);var path=exported.ActiveTarget.OutputPath!;var check=DocumentColorWorkflowV1.Inspect(path,exported.ActiveTarget.LinearRawMaster!,exported.ActiveTarget.RawDefinition!,format);Assert.AreEqual(format==StudioExportFormat.Jpeg?8:16,check.BitDepth);exports.Add(new{format,path,check});if(format==StudioExportFormat.Tiff){var renderer=new RAWSelectionAssistant.Services.Publishing.WpfPublishingRenderer();var publishing=Path.Combine(dir,"published.tif");await renderer.RenderAsync(path,publishing,new(new(Mode:PublishingSizeMode.Exact,Width:80,Height:56),true,[new(Guid.NewGuid(),WatermarkLayerType.Text,Text:"Wide V2",Opacity:.4)],PublishingOutputFormat.Tiff,OutputBitDepth:PublishingOutputBitDepth.Sixteen,ColorSpaceProfile:"DisplayP3"));using var stream=File.OpenRead(publishing);var read=TiffReadBack.Read(stream);Assert.AreEqual(80,read.Width);Assert.AreEqual(56,read.Height);using var cms=new LcmsRgbEngine();CollectionAssert.AreEqual(cms.StandardProfile("DisplayP3").Bytes(),read.IccProfile.ToArray());}}
  vm.EnableLightPrintWorkspace();vm.InstantCameraAnimation=false;vm.InstantEngineVersion="V3";vm.InstantInputMode="CurrentEdits";vm.SelectFilmPaper("itype-color");vm.SelectFilmFrame("generic.dots.square");vm.FavoriteFilmResource("paper:itype-color");vm.FavoriteFilmResource("frame:generic.dots.square");vm.SetFilmResourceFilter("","收藏");Assert.AreEqual(1,vm.FilteredFilmPapers.Count);Assert.AreEqual(1,vm.FilteredFilmFrames.Count);vm.InstantV3Seed=42;vm.InstantV3Exposure=.35;vm.SaveFilmDraft();vm.InstantV3Exposure=.8;vm.RestoreFilmDraft();Assert.AreEqual(.35,vm.InstantV3Exposure);Assert.AreEqual(42UL,Convert.ToUInt64(vm.InstantV3Seed));await vm.LightPrintPreviewWork;await vm.SaveSessionAsync(project);using var resourceReopen=new ReferenceColorWorkspaceViewModel(new Dialogs(Path.Combine(dir,"resource-reopen")));await resourceReopen.LoadSessionAsync(project);resourceReopen.EnableLightPrintWorkspace();resourceReopen.RestoreFilmDraft();Assert.AreEqual(.35,resourceReopen.InstantV3Exposure);Assert.IsTrue(resourceReopen.R53FavoriteResources.Contains("paper:itype-color"));
  var view=new PhotoGradePageView{DataContext=vm};view.Measure(new Size(1920,1080));view.Arrange(new Rect(0,0,1920,1080));view.UpdateLayout();typeof(PhotoGradePageView).GetMethod("R53InstantTab",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(view,new object[]{view,new RoutedEventArgs()});Assert.AreEqual(Visibility.Collapsed,((FrameworkElement)view.FindName("FrameSection")).Visibility);Assert.AreEqual(Visibility.Collapsed,((FrameworkElement)view.FindName("PaperPickerSection")).Visibility);var picker=(InstantV3Editor)view.FindName("V3Editor");Assert.IsTrue(picker.Parent is Panel,"Unique real paper selector belongs to left resource rail");view.UpdateLayout();var visual=Environment.GetEnvironmentVariable("KITAO_COLOR_TOOLS_VISUAL");if(visual is not null){Directory.CreateDirectory(visual);var image=new RenderTargetBitmap(1920,1080,96,96,PixelFormats.Pbgra32);image.Render(view);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using var stream=File.Create(Path.Combine(visual,"film-resource-offscreen.png"));png.Save(stream);}await vm.LightPrintPreviewWork;Assert.AreEqual(42UL,vm.InstantV3Seed,"Project draft seed survives save/view lifecycle");await vm.PreviewPhotographerPapersCommand.ExecuteAsync(null);var count=vm.ActiveTarget.EditVersions.Count;await vm.DevelopLightPrintCommand.ExecuteAsync(null);Assert.IsTrue(vm.IsLightPrintLocked,vm.StatusText);Assert.AreEqual(42UL,vm.ActiveTarget.RawDefinition!.InstantFilm!.V3!.Random.RootSeed,"Final frozen recipe seed");Assert.IsNotNull(vm.ActiveTarget.RawDefinition!.InstantInput!.ColorDocument!.ColorState);Assert.AreEqual(id,vm.ActiveTarget.RawDefinition.InstantInput.OriginVersionId);Assert.AreEqual(2,vm.ActiveTarget.RawDefinition.InstantInput.ColorDocument.LocalEdits!.Stack.Nodes[0].WideToolVersion);Assert.AreEqual(count+1,vm.ActiveTarget.EditVersions.Count);await vm.DevelopLightPrintCommand.ExecuteAsync(null);Assert.AreEqual(count+1,vm.ActiveTarget.EditVersions.Count);var film=Path.Combine(dir,"film.ptstudio.json");await vm.SaveSessionAsync(film);var rendered=ProfessionalRawPipeline.RenderPreview(vm.ActiveTarget.LinearRawMaster!,vm.ActiveTarget.RawDefinition,1600);using var renderedOwner=rendered;File.WriteAllText(Path.Combine(dir,"FILM_HASH.txt"),Convert.ToHexString(SHA256.HashData(System.Runtime.InteropServices.MemoryMarshal.AsBytes(rendered.Rgb32.Span))));view.DataContext=null;Assert.AreEqual(hash,Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(input))));File.WriteAllText(Path.Combine(dir,"RESULT.json"),JsonSerializer.Serialize(new{inputHash=hash,pixelHash,exports,wideSession=project,filmSession=film,originVersion=id,filmVariant=vm.ActiveTarget.ActiveEditVersionId,seed=42,sourceUnchanged=true,filmDomain="full document result/profile -> encoded sRGB film; no monitor transform",pid=Environment.ProcessId},new JsonSerializerOptions{WriteIndented=true}));
 });
 [TestMethod]public Task IndependentProcessWideToolsAndFilmReopen()=>RunSta(async()=>{
  var dir=Environment.GetEnvironmentVariable("KITAO_COLOR_TOOLS_REOPEN");if(dir is null){Assert.Inconclusive("Explicit prior process session required");return;}EnsureTestApplication();using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(Path.Combine(dir,"independent")));await vm.LoadSessionAsync(Path.Combine(dir,"wide-tools.ptstudio.json"));using var result=DocumentColorWorkflowV1.RenderResult(vm.ActiveTarget!.LinearRawMaster!,vm.ActiveTarget.RawDefinition!,vm.ActiveTarget.ActiveEditVersionId);Assert.AreEqual(File.ReadAllText(Path.Combine(dir,"wide-hash.txt")),Convert.ToHexString(SHA256.HashData(System.Runtime.InteropServices.MemoryMarshal.AsBytes(result.Pixels.Rgb32.Span))));await vm.LoadSessionAsync(Path.Combine(dir,"film.ptstudio.json"));using var pixels=ProfessionalRawPipeline.RenderPreview(vm.ActiveTarget!.LinearRawMaster!,vm.ActiveTarget.RawDefinition!,1600);Assert.AreEqual(File.ReadAllText(Path.Combine(dir,"FILM_HASH.txt")),Convert.ToHexString(SHA256.HashData(System.Runtime.InteropServices.MemoryMarshal.AsBytes(pixels.Rgb32.Span))));File.WriteAllText(Path.Combine(dir,"PROCESS_REOPEN.json"),JsonSerializer.Serialize(new{pid=Environment.ProcessId,wideExact=true,filmExact=true,scope="Independent testhost not physical mouse"}));
 });
